SELECT COUNT(*)

WHERE r.is_deleted = 0

    AND r.product_name LIKE CONCAT('%', #{keyword}, '%')


    AND o.order_no LIKE CONCAT('%', #{orderNo}, '%')


    AND r.rating = #{rating}


    AND r.is_virtual = #{isVirtual}


    AND r.status = #{status}


    AND r.created_at >= #{start}


    AND r.created_at <= #{end}

SELECT id, COALESCE(NULLIF(title, ''), name) AS title, image
FROM products
WHERE id = #{productId}
